from taf.gnb.oam.coam.vdu.releases.vduoam26r1 import vDUOAM26R1
from taf.gnb.oam.coam.vdu.schemas.fh.set_ret_configuration_response import Operation


class vDUOAM26R2(vDUOAM26R1):
    def set_ret_configuration(self, target_dn="", timeout=30, use_m2m=True, raw=False, **kwargs):
        """
        Starting from 26R2 (CB014839) new parameter alias_label is introduced.
        target_dn becomes optional if alias_label is provided.
        """
        if use_m2m:
            response = self.fh_licensed_v1.set_ret_configuration(target_dn=target_dn,
                                                                 timeout=timeout,
                                                                 **kwargs)
        else:
            response = self.fh_v1.set_ret_configuration(target_dn=target_dn,
                                                        timeout=timeout,
                                                        **kwargs)

        return response if raw else Operation.from_object_dict(response)
